<?php require_once 'partials.php';if(logged()){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$user=trim($_POST['user']??'');$pass=$_POST['senha']??'';try{if(!preg_match('/^[A-Za-z0-9._-]{3,120}$/',$user))throw new RuntimeException('Use ao menos 3 caracteres no usuário.');if(strlen($pass)<8)throw new RuntimeException('A senha deve ter no mínimo 8 caracteres.');$q=db()->prepare("INSERT INTO usuario(`user`,senha_crip,tipo_user) VALUES(?,?,'convidado')");$q->execute([$user,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'user'=>$user,'tipo_user'=>'convidado'];header('Location:index.php');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Esse usuário já existe.';}}page_top('Cadastro de convidado');?>
<section class="login-layout"><div class="login-intro"><span class="eyebrow">SOLICITANTE</span><h1>Solicite sua<br><em>corrida.</em></h1><p>Crie seu acesso para cadastrar e acompanhar o andamento da solicitação.</p></div><form class="card login-card" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><h2>Criar acesso</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><label>Usuário<input name="user" required minlength="3"></label><label>Senha<input type="password" name="senha" required minlength="8"></label><button class="btn primary">Criar e entrar →</button><a class="btn secondary guest-entry" href="login.php">Voltar ao login</a></form></section><?php page_bottom();?>
